/// <summary>
/// Extension of <c>ReqCalc</c> to trigger the MRP run completed business event.
/// </summary>
[ExtensionOf(classStr(ReqCalc))]
final class AAXReqCalc_Class_Extension
{
}

Method.Source:
/// <summary>
/// Triggers the MRP run completed business event after the master planning run finishes.
/// </summary>
void run()
{
    next run();

    if (BusinessEventsConfigurationReader::isBusinessEventEnabled(classStr(AAXMRPRunCompletedBusinessEvent)))
    {
        AAXMRPRunCompletedBusinessEvent::construct(this.parmReqPlanId()).send();
    }
}
